policy:
{
  // A grant's "via" list names gateway nodes that traffic must pass through to
  // reach the dst. The gateway has to advertise (and have approved) a route
  // covering the dst prefix. Reachability shows in the Routes & exit nodes panel
  // as a route:<prefix>@<gateway> column.
  //
  // There's no checklist — watch the Routes panel and the matrix:
  //   - app-1 -> route:10.99.0.0/24@relay is allowed on 80
  //   - drop the "via" and app-1 reaches the prefix directly (still via the
  //     approved route, but no gateway is enforced)
  //   - change ip to tcp:443 and the route column goes red
  "tagOwners": {
    "tag:app": ["alice@example.com"],
    "tag:relay": ["alice@example.com"],
  },
  "grants": [
    { "src": ["tag:app"], "dst": ["10.99.0.0/24"], "ip": ["tcp:80"], "via": ["tag:relay"] },
  ],
}
